  const notificationsEnabled = getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {notificationsEnabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
